-- Daily challenges for 2026-10-08: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-08

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('easing-holiday-stress', 'Easing Holiday Stress', 'For anyone who loves the holidays and still finds them exhausting, or dreads them outright. Each day is one small way to plan, pace, and protect your energy through gatherings, travel, spending and family expectations, so the season has more room for what matters to you.', 'Stress', 365, array['Stress', 'Family', 'Boundaries']::text[], 1, '2026-10-08T17:00:00+00:00'::timestamptz),
  ('steadying-yourself-through-change', 'Steadying Yourself Through Change', 'For anyone going through a move, a new job, a breakup, a new baby, retirement or any big shift. Each day is one small way to find steady ground, keep a few anchors in place, and give yourself time to adjust.', 'Transitions', 365, array['Life Transitions', 'Resilience']::text[], 1, '2026-10-08T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('easing-holiday-stress', 'steadying-yourself-through-change');

